'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='jd-engineering-course-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const state={done:{},notes:{},answers:{},quiz:{},project:{},drafts:{},checks:{},review:{},readerPositions:{},positions:{},projectStages:{},disclosures:{},route:'foundation',...saved};
let course,chapters=[],lessons=[],sourceData=null,activeLayer='power',systemSelection='power',sourcePage=15,toastTimer,activeRoute='',activeSourceKey='book',positionTimer,searchSerial=0;
const store=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器存储不可用，请导出笔记保存。')}};
const toast=s=>{$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)};
const pc=(a,b)=>b?Math.round(a/b*100):0;
const chapterDone=c=>c.lessons.filter(l=>state.done[l.id]).length;
const unitHref=(id,mode='')=>`#lesson/${id}${mode?'/'+mode:''}`;
const chapterHref=id=>`#chapter/${id}`;
const getChapter=id=>chapters.find(c=>c.id===Number(id));
const getLesson=id=>lessons.find(l=>l.id===id);
const range=p=>`原书 pp. ${p[0]}–${p[1]}`;
const phases=[{n:'01',title:'建立工程全局',desc:'从业务连续性出发，定义需求与边界',chapters:'第 1 章',id:1},{n:'02',title:'追踪电力与热量',desc:'供配电、UPS、冷却与后备发电的协同',chapters:'第 2–5 章',id:2},{n:'03',title:'让系统可见、可管、可维护',desc:'智能化、布线、消防与建筑环境',chapters:'第 6–9 章',id:6},{n:'04',title:'在真实案例中闭环',desc:'回到京东华东数据中心，验证设计与运营',chapters:'第 10 章 + 综合评审',id:10}];
const systems={
 power:{title:'电力路径',en:'POWER CONTINUITY',chapters:[2,3,5],flow:'市电 / 发电机 → 配电 → UPS → 末端配电 → IT 负载',body:'沿一台服务器向上追溯，冗余必须覆盖供电设备、分配路径和切换环节。UPS 连接短时中断与后备电源建立，发电机还依赖燃油、启动、通风和控制。',questions:['两路电源是否仍然经过同一个上游节点？','计划维护时，剩余路径能否承担全部需要的负荷？','市电中断期间，制冷与控制系统由谁供电？'],dependency:'向制冷系统提供动力；接受监控与联动信号；依赖建筑、接地与消防边界。'},
 cooling:{title:'热量路径',en:'THERMAL CONTINUITY',chapters:[4,5,10],flow:'芯片 → 机柜气流 → 空调末端 → 冷源 → 室外环境',body:'冷量足够并不保证服务器进风合适。热量需要经过完整的传递路径；短路回风、旁通气流、泵阀状态与冷源恢复时间都可能形成瓶颈。',questions:['冷风真正到达了机柜进风口吗？','电力恢复后，制冷是否已经恢复？','局部节能是否增加了另一环节的能耗？'],dependency:'依赖电力、传感器与控制；反过来约束 IT 功率密度、建筑布局和备用时间。'},
 network:{title:'信息路径',en:'CONNECTIVITY',chapters:[7,9,10],flow:'外部接入 → 配线区域 → 主干 → 列 / 柜 → IT 设备',body:'逻辑冗余需要真实的物理路由支撑。连接器、跳线、标签、通道和测试记录组成了一条可追溯的信息路径，网络拓扑变化也会改变布线边界。',questions:['两条逻辑链路是否共用同一物理通道？','更换一根跳线时能否可靠识别两端？','扩容会不会破坏气流、通行或防火分隔？'],dependency:'受建筑空间、走线、消防分区影响；依赖供电；与资产和变更管理保持一致。'},
 monitoring:{title:'感知与控制',en:'OBSERVE · ACT · VERIFY',chapters:[6,10],flow:'传感与采集 → 传输与处理 → 设备管理 → 可视化 → 应用',body:'从看到数据到完成管理，中间还需要可信采集、统一语义、告警责任、控制边界与处置反馈。界面显示正常只是证据链的一部分。',questions:['失联与正常数值是否被清楚区分？','一条告警由谁确认、处置、复核？','平台自身故障时，本地控制还能否正常工作？'],dependency:'连接供配电、冷源与安防；依赖自身供电和网络；向运维提供可执行的证据。'},
 safety:{title:'安全边界',en:'BOUNDARIES & PROTECTION',chapters:[1,8,9],flow:'选址与分区 → 建筑防护 → 检测与告警 → 人员响应',body:'安全条件从规划、材料和空间布局阶段形成。消防、漏水、静电、粉尘与人员通行都与日常维护发生交集，需要跨专业核验。',questions:['穿墙与穿楼板处是否延续了原有边界？','设备的防护是否与人员安全、疏散兼容？','后期改造是否重新验证了空间和材料条件？'],dependency:'与电气保护、燃油、制冷用水、线缆及设备运输接口相连。'},
 operations:{title:'运维闭环',en:'DESIGN FOR OPERATIONS',chapters:[5,6,10],flow:'设计输入 → 验收基线 → 巡检监测 → 变更 / 处置 → 复盘',body:'设计可靠性需要在长期运行中保持。原书案例把运维介入、制度、人员和平台一起讨论，让隐患、变更和经验可以被持续追踪。',questions:['设备退出运行后，可靠性目标还成立吗？','竣工图、平台数据和现场状态是否一致？','每次事件是否留下可复用的改进记录？'],dependency:'贯穿全部系统，把纸面方案转化成持续可验证的运行状态。'}
};
const glossary=[['N / N+1 / 2N','N 是承担设计需求所必需的容量；N+1 增加一个容量组件；2N 表示两套各能承载需求的容量配置。实际可靠性还取决于分配路径与共同依赖。'],['可并行维护','在不影响关键负载运行的前提下，使相关容量或分配组件能够退出服务进行计划维护。必须沿完整路径分析。'],['容错','在所规定的故障条件下维持关键功能。需要检查故障的传播范围与系统隔离，不能从设备数量直接推出。'],['UPS','不间断电源。用能量储备和变换环节支持负载跨越供电中断；具体工作方式、旁路与故障模式需要分别分析。'],['ATSE','自动转换开关电器。用于电源之间的转换。切换的条件、时间、负载兼容性与维护安排都是设计问题。'],['HVDC','本书中的高压直流供电系统，重点介绍 240 V 直流方案。课程保留该历史技术语境，不等同于高压输电的 HVDC。'],['选择性保护','故障时尽量由最接近故障的保护环节切除受影响部分，避免扩大停电范围。选择性需要依据设备数据与协调分析验证。'],['旁路','为特定工况提供替代供电路径。旁路的电源、保护与可维护性可能改变原有冗余条件。'],['显热 / 潜热','显热对应温度变化；潜热涉及相变与湿量变化。机房热负荷分析要区分二者的来源与处理方式。'],['COP','制冷量与相应输入功率的比值。比较前需明确设备、工况和测量边界；单机数值不能代表全站能效。'],['PUE','同一边界、同一统计周期内，数据中心总能耗与 IT 设备能耗之比。它描述基础设施能耗关系，不直接代表 IT 产出或可靠性。'],['冷 / 热通道','通过机柜朝向与空间组织分开进风和排风，减少冷热气流混合。封闭方式需与回风、消防和维护条件协同。'],['自然冷却','在适合的外部环境条件下利用室外冷源减少机械制冷需求。可用时长和收益依赖气候、系统边界及控制策略。'],['BMS / 楼宇自控','通过传感、控制器和执行器管理机电系统。与集中监控之间应明确数据与控制职责。'],['ToR / EoR / MoR','柜顶 / 列端 / 列中交换机布置方式。会改变铜缆和光纤长度、交换机数量、端口利用率及维护边界。'],['POD','将计算、网络及相关基础设施组织为可重复的模块单元。模块边界需要匹配扩容、故障隔离和运维方式。'],['共因故障','一个共同原因同时影响多个原本被视为冗余的部分。例如共用上游、空间或控制环节。'],['证据链','把设计假设、图纸、测试、现场状态和运维记录连接起来，让“系统满足要求”成为可以复核的判断。']];

function diagram(layer=activeLayer){
 let racks='';for(let r=0;r<2;r++)for(let c=0;c<5;c++){const x=112+c*46-r*35,y=117+c*16+r*36;racks+=`<g><path d="M${x},${y} l27,-15 25,14 -27,15z" fill="#cfd5c5"/><path d="M${x},${y} v81 l25,15 v-81z" fill="#b7c0ad"/><path d="M${x+25},${y+15} l27,-15 v81 l-27,15z" fill="#e3e6d9"/><path d="M${x},${y} l27,-15 25,14 v81 l-27,15 -25,-15z M${x+25},${y+15} v81 M${x+25},${y+15} l27,-15" fill="none" stroke="#7e8e72" stroke-width=".65"/>${[25,39,53,67].map(a=>`<path d="M${x+30},${y+a} l17,-9" stroke="#9aa88c"/><circle cx="${x+46}" cy="${y+a-6}" r="1.1" fill="${layer==='monitoring'?'#bf3c30':'#6e845a'}"/>`).join('')}</g>`;}
 const path=layer==='cooling'?'M67 271 L296 350 L418 277 M70 255 L300 334 L416 266':layer==='network'?'M91 118 L333 202 L402 164 M91 109 L333 193 L402 155':'M66 278 L294 357 L432 277 M82 288 L82 235 M287 349 L287 309 M407 291 L407 265';
 return `<svg viewBox="0 0 500 390" role="img" aria-label="教学示意：机柜、${systems[layer]?.title||'电力'}及空间布局"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#dce1d2" stroke-width=".5"/></pattern></defs><rect width="500" height="390" fill="url(#grid)"/><path d="M40 232 L188 148 L468 247 L309 347z" fill="#e0e4d5" stroke="#a3b195" stroke-width=".7"/><path d="M40 232v10l269 115 159-100v-10 M309 347v10" stroke="#a3b195" stroke-width=".7" fill="none"/>${racks}<path d="${path}" stroke="${layer==='cooling'?'#628aa0':'#bb5140'}" stroke-width="2.7" fill="none" stroke-linecap="round"/><path d="M112 116 L65 98 H31 M366 201 L433 179 H469 M310 354 V374 H422" stroke="#9da990" stroke-width=".7" fill="none"/><circle cx="112" cy="116" r="3" fill="#77866b"/><circle cx="366" cy="201" r="3" fill="#77866b"/><text x="30" y="89" fill="#78886b" font-size="9" font-family="sans-serif">IT 负载</text><text x="425" y="169" fill="#78886b" font-size="9" font-family="sans-serif">${layer==='cooling'?'热量排出':layer==='network'?'物理链路':layer==='monitoring'?'采集信号':'供电路径'}</text><text x="355" y="368" fill="#78886b" font-size="9" font-family="sans-serif">基础设施协同</text></svg>`;
}
function sidebar(){const hash=location.hash||'#home';const current=hash.split('/')[1];const l=hash.startsWith('#lesson')?getLesson(current):null;const cid=l?.chapterId||(hash.startsWith('#chapter')||hash.startsWith('#project')?Number(current):hash.startsWith('#book-page')?chapters.find(c=>Number(current)>=c.bookRange[0]&&Number(current)<=c.bookRange[1])?.id:null);const done=Object.keys(state.done).filter(id=>getLesson(id)&&state.done[id]).length;
 $('#sidebar').innerHTML=`<a class="brand" href="#home"><span class="brand-mark">▤</span><span><strong>机房之外</strong><small>DATA CENTER FIELDNOTES</small></span></a><div class="nav-label">LEARNING WORKSPACE</div><nav class="side-nav">${[['home','⌂','学习总览'],['book-guide','◉','全书导读'],['original','文','逐字原文'],['course','▤','全书学习路径'],['systems','⌘','系统关系图'],['labs','⊞','交互实验室'],['case','◇','京东案例 · 综合评审'],['synthesis','⇄','全书贯通'],['review','↺','回忆与再练'],['notes','▧','我的学习记录']].map(([r,i,t])=>`<a href="#${r}" class="${hash.startsWith('#'+r)?'active':''}"><span class="nav-icon" aria-hidden="true">${i}</span>${t}</a>`).join('')}</nav><div class="nav-label">CHAPTERS / 原书十章</div><nav class="side-chapters">${chapters.map(c=>`<a href="#chapter/${c.id}" class="${cid===c.id?'active':''}"><span class="num">${String(c.id).padStart(2,'0')}</span>${esc(c.shortTitle)}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-book">你的学习进度<strong>${done} / ${lessons.length} 个学习单元</strong><div class="mini-progress"><i style="width:${pc(done,lessons.length)}%"></i></div><span>保存在当前浏览器</span><a href="#sources" class="text-link" style="display:block;margin-top:20px">原书索引与内容说明 ↗</a></div></div>`;
}
function setCrumb(text){$('#breadcrumb').innerHTML=`<a href="#home">工程研习</a><span>/</span>${esc(text)}`;document.title=`${text} · 机房之外`;}
function home(){setCrumb('学习工作台');const previous=getLesson(state.lastLesson);const resume=(previous&&!state.done[previous.id]?previous:null)||lessonOrder().find(l=>!state.done[l.id])||lessonOrder()[0];const done=lessons.filter(l=>state.done[l.id]).length;
 return `<section class="hero"><div><div class="eyebrow"><span class="dot"></span>一本工程实践书的深度学习之旅</div><h1>读懂一座<br><em>持续运行</em>的数据中心。</h1><p class="description">从电力流向到热量去向，从一张系统图到一次运维决策。沿着《京东数据中心构建实战》的十章内容，理解每个选择背后的约束、取舍与联系。</p><div class="buttons"><a class="button primary" href="${esc(state.lastLocation||unitHref(resume.id))}">${state.lastLocation||state.lastLesson?'继续学习':'开启第一课'} <span>↗</span></a><a class="button" href="#course">探索课程路径 <span>→</span></a></div><div class="hero-meta"><span><b>10</b> 原书章节</span><span><b>${lessons.length}</b> 学习单元</span><span><b>4</b> 交互实验</span><span><b>1</b> 综合项目</span></div></div><div class="hero-art"><div class="blueprint-label">FIG. 01 / THE SYSTEM BEHIND THE RACK</div><div class="blueprint-label right">教学示意</div><div class="svg-wrap" id="hero-diagram">${diagram()}</div><div class="system-switch" aria-label="切换系统示意">${[['power','电力'],['cooling','热量'],['network','连接'],['monitoring','感知']].map(([k,t])=>`<button data-layer="${k}" class="${activeLayer===k?'active':''}" aria-pressed="${activeLayer===k}">${t}</button>`).join('')}</div><div class="diagram-highlight" id="diagram-highlight">${esc(systems[activeLayer].flow)}</div></div></section>
 <div class="focus-strip"><span class="big-num">${String(resume.chapterId).padStart(2,'0')}</span><div><small>从一个问题开始 / YOUR NEXT QUESTION</small><p><strong>${esc(resume.question)}</strong></p><small>第 ${resume.chapterId} 章 · ${esc(resume.title)} · 示范 / 变式 / 独立练习</small></div><a class="button small" href="${unitHref(resume.id)}">进入学习 →</a></div>
 <div class="home-columns"><section><div class="section-head"><h2>把全书连成一条路<span class="en">THE LEARNING PATH</span></h2><a href="#course" class="text-link">查看全部 →</a></div><div class="path-list">${phases.map(p=>`<a class="path-step" href="#chapter/${p.id}"><div class="path-index">${p.n}</div><div><div class="path-title">${p.title}</div><div class="path-desc">${p.desc}<br><span>${p.chapters}</span></div></div><span class="path-arrow">↗</span></a>`).join('')}</div></section><section><div class="section-head"><h2>带着这个问题读</h2><span class="tag">本书主线</span></div><div class="insight-panel"><div class="eyebrow">ENGINEERING INSIGHT / 01</div><h3>多一台设备，<br>就多一份可靠吗？</h3><p>冗余容量、独立路径和维护条件，是三个需要分别回答的问题。一个共同的上游节点，就可能改变整套架构的表现。</p><a class="text-link" href="#labs/redundancy">在故障实验中试一试 →</a></div><div class="metric-row"><div><strong>${pc(done,lessons.length)}<small style="display:inline">%</small></strong><small>学习单元完成度</small></div><div><strong>${Object.keys(state.quiz).filter(x=>state.quiz[x]?.passed&&state.quiz[x]?.version===deepCourse.version).length}<small style="display:inline"> / 10</small></strong><small>章节检验通过</small></div></div></section></div>
 <div class="section-head"><h2>让理解发生在操作中<span class="en">LEARN BY CHANGING</span></h2><a href="#labs" class="text-link">进入实验室 →</a></div><div class="lab-preview"><a href="#labs/redundancy"><span class="lab-symbol">N+1</span><div><h3>改变一处故障，看清冗余的边界</h3><p>容量、路径、共因故障 · 第 2 / 3 章</p></div></a><a href="#labs/cooling"><span class="lab-symbol">ΔT</span><div><h3>让热量与能耗的关系变得可见</h3><p>气流、温差、PUE 边界 · 第 4 / 10 章</p></div></a></div>`;
}
function coursePage(){setCrumb('全书学习路径');const orders=LearningCore.routes;const desc={foundation:'按原书顺序建立完整认识。每课都有研读、决策情境、主动回忆和一份小型交付物。',design:'先确定业务边界，再分析供电与冷却，最后让建筑、安全和管理形成整体。此路线调整顺序，保留全部十章。',operations:'先建立系统全局，再借监控与京东案例提出问题，回到各专业学习故障边界与维护条件。'};
 return `<div class="eyebrow">THE BOOK, RECONSTRUCTED FOR LEARNING</div><h1 class="page-title">从读懂设备，到理解系统。</h1><p class="page-intro">原书前九章拆解基础设施，第十章把它们重新放回真实工程。课程保留原章顺序与页码，同时让每个知识点连接到判断、练习和现场证据。</p><div class="route-picker" aria-label="选择学习路线">${[['foundation','完整研读'],['design','设计视角'],['operations','运维视角']].map(([v,t])=>`<button data-route="${v}" class="${state.route===v?'active':''}" aria-pressed="${state.route===v}">${t}</button>`).join('')}</div><div class="route-description">${desc[state.route]||desc.foundation}</div><div class="chapter-table">${(orders[state.route]||orders.foundation).map(id=>{const c=getChapter(id);return `<a class="chapter-row" href="#chapter/${id}"><span class="chapter-no">${String(id).padStart(2,'0')}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.question)}</p></div><div class="chapter-range">${c.lessons.length} 个学习单元<br>pp. ${c.bookRange.join('–')}</div><div class="chapter-status">${chapterDone(c)} / ${c.lessons.length} 已完成<div class="mini-progress"><i style="width:${pc(chapterDone(c),c.lessons.length)}%"></i></div></div></a>`}).join('')}</div><div class="callout"><div class="label">怎样使用这门课</div><p>先回答开场问题，再读作者的分析；尝试情境选择后，解释自己为什么这样选；写下带有约束条件的结论。完成章节检验后，到系统关系图重建一次跨章节联系。</p></div>`;
}
function chapterPage(c){setCrumb(`第 ${c.id} 章 · ${c.shortTitle}`);return `${chapterLearningTabs(c,'overview')}<div class="chapter-header"><div><div class="eyebrow">CHAPTER ${String(c.id).padStart(2,'0')} / ${range(c.bookRange)}</div><h1>${esc(c.title)}</h1><p class="question">${esc(c.question)}</p><p class="page-intro">${esc(c.summary)}</p><div class="buttons"><a class="button primary" href="${unitHref(c.lessons.find(l=>!state.done[l.id])?.id||c.lessons[0].id)}">进入本章学习 →</a><a class="button" href="#chapter/${c.id}/quiz">章节理解检验</a></div></div><div class="goals-box"><h3>学完本章，你应该能够</h3><ol>${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ol></div></div><div class="author-intent"><h3>作者的思路<br><small>据原书归纳</small></h3><p>${esc(c.authorIntent)}</p></div>${learningLoopHTML(c)}<div class="section-head"><h2>本章学习单元</h2><small>${chapterDone(c)} / ${c.lessons.length} 已完成</small></div><ol class="lesson-list">${c.lessons.map(l=>`<li><a href="${unitHref(l.id)}"><span class="lesson-index">${esc(l.section)}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.question)}</p></div><span class="tag ${state.done[l.id]?'green':''}">${state.done[l.id]?'✓ 已完成':'进入研习'}</span></a></li>`).join('')}</ol><div class="section-head"><h2>把本章放回全书</h2><a class="text-link" href="#systems">查看系统关系 →</a></div><div class="connections">${c.connections.map(x=>`<a href="#chapter/${x.to}">第 ${x.to} 章 · ${esc(getChapter(x.to)?.shortTitle||'关联章节')}<small>${esc(x.why)}</small></a>`).join('')}</div>`;}
function lessonPage(l,tab='read'){
 const c=getChapter(l.chapterId),d=deepLesson(l.id),mode=['read','details','source','check'].includes(tab)?tab:'read';
 state.lastLesson=l.id;store();setCrumb(`第 ${c.id} 章 · ${l.title}`);
 const {previous,next}=LearningCore.neighbors(chapters,state.route,l.id);
 let content=mode==='details'?lessonDetailsHTML(l):mode==='source'?sourceReader(state.readerPositions[l.id]||l.bookPages[0]+14,l.id):mode==='check'?(deepExerciseHTML(l)||exerciseHTML(l)):deepReadHTML(l);
 if(!content)content=`<div class="callout"><p>${esc(l.lead)}</p></div><div class="prose">${l.sections.map((s,i)=>`<section id="section-${i}"><h2>${esc(s.title)}</h2>${s.body.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}</div>${decisionHTML(l)}<a class="button primary" href="#lesson/${l.id}/check">主动回忆与练习 →</a>`;
 const headings=d?.blocks?.map((b,i)=>({...b,index:i})).filter(b=>b.type==='heading')||[];
 return `<div class="reader-layout"><article><header class="reader-head"><a class="text-link" href="#chapter/${c.id}">← ${esc(c.title)}</a><div class="eyebrow" style="margin-top:27px">LESSON ${esc(l.section)} / 研读 · 示范 · 迁移</div><h1 class="page-title">${esc(l.title)}</h1><p class="lead">${esc(l.question)}</p><div class="buttons"><span class="tag">${range(l.bookPages)}</span><a class="tag" href="#chapter/${c.id}/insight">本章思想研习 ↗</a>${state.done[l.id]?'<span class="tag green">✓ 已记录学习完成</span>':''}</div></header><nav class="reader-tabs">${[['read','研读与示范'],['details','原书细读'],['check','练习与反馈'],['source','原页核对']].map(([key,t])=>`<a class="${mode===key?'active':''}" ${mode===key?'aria-current="page"':''} href="#lesson/${l.id}/${key}">${t}</a>`).join('')}</nav>${content}<p class="learning-route-label">当前路线：${{foundation:'完整研读',design:'设计视角',operations:'运维视角'}[state.route]}</p><div class="lesson-bottom">${previous?`<a class="text-link" href="${unitHref(previous.id,mode)}">← 上一课：${esc(previous.title)}</a>`:`<a class="text-link" href="#chapter/${c.id}">← 返回本章</a>`}${next?`<a class="text-link" href="${unitHref(next.id,mode)}">下一课：${esc(next.title)} →</a>`:'<a class="text-link" href="#case">前往综合评审 →</a>'}</div></article><aside class="reading-rail"><h3>本课导览</h3>${mode==='read'?headings.map(h=>`<a href="#deep-${l.id}-${h.index}" data-scroll="deep-${l.id}-${h.index}">${esc(h.text)}</a>`).join(''):`<a href="#lesson/${l.id}/read">回到研读课程</a>`}<div class="source-ref"><h3>原书位置</h3><p>第 ${c.id} 章 · ${esc(l.section)} 节<br>书页 ${l.bookPages.join('–')}</p><a class="text-link" href="#chapter/${c.id}/coverage">逐项内容地图 ↗</a></div><div class="source-ref"><a href="#project/${c.id}">把本课放进工程档案 →</a></div></aside></div>`;
}
function decisionHTML(l){const a=state.answers[l.id];const answered=Number.isInteger(a)&&!!l.decision.options[a];return `<section class="decision" data-decision="${l.id}"><div class="eyebrow">YOUR TURN / 先做一个判断</div><h3>${esc(l.decision.scenario)}</h3>${l.decision.options.map((o,i)=>`<button class="choice ${answered&&a===i?(i===l.decision.answer?'correct':'chosen'):''}" data-answer="${l.id}" data-option="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o.text)}</button>`).join('')}<div class="feedback ${answered&&a!==l.decision.answer?'wrong':''}" role="status">${answered?`${a===l.decision.answer?'判断成立。':'再检查一下你的前提。'} ${esc(l.decision.options[a]?.feedback)}`:'选一个答案，再看它背后的工程理由。'}</div></section>`;}
function exerciseHTML(l){return `<div class="eyebrow">RETRIEVAL PRACTICE / 先在脑中作答</div><h2 style="font-family:var(--serif);font-size:24px;margin:14px 0 24px">离开原文，你还能解释吗？</h2>${l.recall.map((q,i)=>`<details class="recall"><summary>${i+1}. ${esc(q.q)}</summary><p>${esc(q.a)}</p></details>`).join('')}${decisionHTML(l)}<section class="practice"><div class="eyebrow">SMALL DELIVERABLE / 把理解落到纸上</div><h3>${esc(l.practice.task)}</h3><p><strong>交付物：</strong>${esc(l.practice.deliverable)}</p><ul>${l.practice.criteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><label class="note-label" for="lesson-note">写下你的结论、成立条件与待核验问题</label><textarea class="note-box" id="lesson-note" data-note="${l.id}" placeholder="尝试说明：我的判断是什么？依赖什么条件？需要什么证据？">${esc(state.notes[l.id]||'')}</textarea><p class="note-help">输入后自动保存于当前浏览器。完成记录表示你已学习并核对本课；请用独立解释与条件变式检验理解。</p><div class="buttons"><button class="button primary" data-complete="${l.id}">${state.done[l.id]?'更新本课完成记录':'完成本课学习'} ✓</button><button class="button" data-export="notes">导出我的笔记</button></div>`;}
function quizPage(c){setCrumb(`第 ${c.id} 章 · 理解检验`);return `<div style="max-width:800px;margin:auto"><a class="text-link" href="#chapter/${c.id}">← 返回本章</a><div class="eyebrow" style="margin-top:30px">CHAPTER CHECK / ${String(c.id).padStart(2,'0')}</div><h1 class="page-title">让判断有依据。</h1><p class="page-intro">${esc(c.title)} · ${c.quiz.length} 道情境题。先完成选择，再提交查看解释。答错后可回到课程，修改答案重新检验。</p><form id="chapter-quiz" data-chapter="${c.id}">${c.quiz.map((q,n)=>`<div class="quiz-question"><h3>${n+1}. ${esc(q.question)}</h3>${q.options.map((o,i)=>`<label class="choice"><input type="radio" name="q${n}" value="${i}" required> ${esc(optionText(o))}</label>`).join('')}<div class="quiz-explanation" id="explain-${n}"></div></div>`).join('')}<div id="quiz-result" aria-live="polite"></div><button class="button primary" style="margin-top:25px" type="submit">提交并查看解析 →</button></form></div>`;}
function systemsPage(){setCrumb('系统关系图');const s=systems[systemSelection];return `<div class="eyebrow">THINK IN SYSTEMS</div><h1 class="page-title">每一条路径，都有它的依赖。</h1><p class="page-intro">选择一个系统，沿着功能路径寻找它的输入、输出与共同节点。下面是课程重构的关系图，用来连接原书章节，不是京东项目的施工图。</p><div class="system-workbench"><div class="system-canvas"><div class="eyebrow" style="color:var(--green)">THE CONNECTED FACILITY</div><div class="system-nodes">${Object.entries(systems).map(([k,v])=>`<button class="system-node ${systemSelection===k?'selected':''}" data-system="${k}" aria-pressed="${systemSelection===k}">${v.title}<small>CH. ${v.chapters.join(' / ')}</small></button>`).join('')}</div><div class="system-core"><strong>IT 服务持续运行</strong><p>电力 · 环境 · 连接 · 可维护性</p></div><div class="dependency-line">${esc(s.flow)}</div><div style="max-width:430px;margin:auto">${diagram(['power','cooling','network','monitoring'].includes(systemSelection)?systemSelection:'power')}</div></div><div class="system-detail"><div class="eyebrow">${s.en}</div><h2>${s.title}</h2><p>${s.body}</p><h3 style="font-size:13px;margin-top:28px">沿着路径追问</h3><ul>${s.questions.map(x=>`<li>${x}</li>`).join('')}</ul><div class="callout"><div class="label">与其他系统的联系</div><p>${s.dependency}</p></div><div class="buttons">${s.chapters.map(n=>`<a class="button small" href="#chapter/${n}">第 ${n} 章 ↗</a>`).join('')}</div></div></div>${systemLearningMap()}<div class="section-head"><h2>把术语接回系统</h2><small>课程释义 · 可结合原书核对</small></div><div class="glossary">${glossary.map(([t,b])=>`<article><h3>${t}</h3><p>${b}</p></article>`).join('')}</div>`;}

const labTypes=[['redundancy','01 冗余与故障'],['bridge','02 电源衔接'],['cooling','03 热量与能耗'],['alarm','04 告警与证据']];
function field(label,id,min,max,value,unit,step=1){return `<div class="field"><label for="${id}">${label}<output id="${id}-value">${value} ${unit}</output></label><input type="range" id="${id}" data-lab-input min="${min}" max="${max}" value="${value}" step="${step}" data-unit="${unit}"></div>`;}
function select(label,id,options,value){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" data-lab-input>${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function labsPage(type='redundancy'){if(type==='alarm')return diagnosticLab();if(!labTypes.some(x=>x[0]===type))type='redundancy';setCrumb('交互实验室');const intro={redundancy:['设备数量，能回答所有问题吗？','改变负载、冗余方式和故障位置。观察容量是否足够，并分辨“容量有余量”与“路径仍然可用”。'],bridge:['短时储能，怎样接上长时保障？','把市电丢失、后备建立与恢复余量放在同一条时间线上。这里使用理想能量模型，展示约束关系。'],cooling:['同一份 IT 负载，热量去向哪里？','先明确计量边界，再分析热量传递。温差变化影响所需风量，PUE 的变化则需要在同一时间周期比较。'],alarm:['看见告警，离判断还有多远？','从一条高温告警出发，选择需要补齐的证据。练习把现象、原因、影响范围和响应职责分开。']}[type];let controls='';if(type==='redundancy')controls=field('IT 设计需求','load',150,1200,600,'kW',50)+field('单模块容量','module',100,500,300,'kW',50)+select('容量配置','topology',[['n','N'],['n1','N+1'],['2n','2N']],'n1')+select('观察的事件','fault',[['normal','正常运行'],['unit','一台容量模块故障'],['path','A 路分配路径维护'],['common','共同上游中断']],'unit')+select('上游关系','shared',[['yes','两路共用上游'],['no','两路上游独立（假设）']],'yes');
if(type==='bridge')controls=field('关键负载','bridge-load',100,1000,600,'kW',50)+field('电池标称能量','battery',10,200,40,'kWh',5)+field('可用能量比例','usable',40,95,80,'%',5)+field('转换效率','efficiency',80,98,92,'%',1)+field('后备电源建立时间','start-time',10,300,60,'秒',10)+field('额外恢复与评估余量','margin',0,300,60,'秒',10);
if(type==='cooling')controls=field('恒定 IT 功率（教学假设）','it',100,1000,600,'kW',50)+field('制冷系统功率','cool-power',20,450,180,'kW',10)+field('其他基础设施功率','other',10,200,60,'kW',10)+field('通过设备的空气温升','delta',5,20,12,'K',1);

return `<div class="eyebrow">LEARNING LAB / 教学模型</div><h1 class="page-title">${intro[0]}</h1><p class="page-intro">${intro[1]}</p><nav class="lab-tabs">${labTypes.map(([v,t])=>`<a href="#labs/${v}" class="${v===type?'active':''}">${t}</a>`).join('')}</nav>${labPrediction(type)}<details class="experiment-result"><summary>02 / 打开实验，改变条件并观察结果</summary><div class="lab-layout" data-lab="${type}"><div class="lab-controls">${controls}<p class="model-note">所有输入均为课程自设的教学假设，可反复改变。模型用于理解关系，不输出设备选型、工程定容或等级认证结论。</p></div><div class="lab-output" id="lab-output" aria-live="polite"></div></div></details>${labReflection(type)}<div class="section-head"><h2>带着实验结果回到书中</h2></div><div class="connections">${(type==='redundancy'?[2,3]:type==='bridge'?[3,5,4]:type==='cooling'?[4,10]:[6,10]).map(id=>`<a href="#chapter/${id}">第 ${id} 章 · ${esc(getChapter(id).shortTitle)}<small>${esc(getChapter(id).question)}</small></a>`).join('')}</div>`;}
function updateLab(){const kind=$('[data-lab]')?.dataset.lab;if(!kind)return;const n=id=>Number($('#'+id).value);$$('[data-lab-input][type=range]').forEach(e=>$('#'+e.id+'-value').textContent=`${e.value} ${e.dataset.unit}`);let html='';
 if(kind==='redundancy'){const demand=n('load'),capacity=n('module'),needed=Math.ceil(demand/capacity),top=$('#topology').value,fault=$('#fault').value,shared=$('#shared').value==='yes';let a=top==='n1'?needed+1:needed,b=top==='2n'?needed:0;const initial=a+b;let aa=a,bb=b;if(fault==='unit')aa=Math.max(0,aa-1);if(fault==='path')aa=0;if(fault==='common'){aa=0;if(shared)bb=0;}const available=(aa+bb)*capacity,ok=available>=demand;html=`<div class="eyebrow">CAPACITY × PATH</div><h3 style="margin-top:15px">${top==='2n'?'两路各自具备 N 容量':top==='n1'?'一条路径，N+1 容量组件':'一条路径，N 容量组件'}</h3><div class="bus-label">A 路 · ${shared?'共用上游':'独立上游假设'}</div><div class="modules">${Array.from({length:a},(_,i)=>`<div class="module ${i>=aa?'failed':''}">${capacity} kW</div>`).join('')}</div>${b?`<div class="bus-label">B 路 · ${shared?'与 A 路共同上游':'与 A 路上游独立'}</div><div class="modules">${Array.from({length:b},(_,i)=>`<div class="module ${i>=bb?'failed':''}">${capacity} kW</div>`).join('')}</div>`:''}<div class="diagram-pipe" style="background:${ok?'#95ac81':'#bf6d51'}"></div><div class="result-metrics"><div class="result-metric"><b>${needed}</b><small>所需 N 值</small></div><div class="result-metric"><b>${available}</b><small>剩余容量 / kW</small></div><div class="result-metric"><b>${demand}</b><small>需求 / kW</small></div></div><div class="state-box ${ok?'':'fail'}">${ok?'在本模型中，剩余容量可覆盖需求。':'在本模型中，剩余路径或容量不足。'} ${fault==='common'&&shared?'共同上游中断会同时影响冗余分支。':fault==='path'&&top!=='2n'?'增加容量组件没有增加独立分配路径。':top==='2n'?'两路均假设能将各自全部容量送达兼容双电源的负载。':'单路径仍是需要单独检查的约束。'}</div><p class="model-note">装机 ${initial*capacity} kW；余量 ${(available-demand)} kW。理想化模型假设组件可均匀分担负荷、故障可隔离、切换成功；忽略效率、过载、保护配合和动态响应。“共同上游”在独立配置下仅影响 A 路。不由本结果推断 Tier 等级。</p><div class="formula">N = ceil(设计需求 ÷ 单模块容量)<br>可用容量 = 可用路径上的组件数量 × 单模块容量</div>`;}
 if(kind==='bridge'){const p=n('bridge-load'),e=n('battery'),u=n('usable')/100,eta=n('efficiency')/100,t=e*u*eta/p*3600,target=n('start-time')+n('margin'),scale=Math.max(t,target)*1.25;html=`<div class="eyebrow">A BRIDGE IN TIME</div><h3 style="margin-top:15px">储能覆盖的是一段恢复过程</h3><div class="timeline"><div class="bar" style="width:${t/scale*100}%"></div><div class="marker" style="left:${target/scale*100}%"><span>后备建立 + 余量</span></div><div class="marker safe" style="left:${t/scale*100}%"><span style="top:13px">理想储能耗尽</span></div></div><div class="result-metrics"><div class="result-metric"><b>${(t/60).toFixed(2)}</b><small>理想支撑时间 / 分钟</small></div><div class="result-metric"><b>${target}</b><small>需覆盖时间 / 秒</small></div><div class="result-metric"><b>${Math.round(t-target)}</b><small>时间差 / 秒</small></div></div><div class="state-box ${t>=target?'':'fail'}">${t>=target?'理想模型的储能窗口覆盖了输入的时间要求。':'输入的恢复时间超出了理想储能窗口。'} 还需要单独检查冷源、控制系统和其他关键辅助负荷在这段时间里的状态。</div><div class="formula">t(秒) = E(kWh) × 可用比例 × 效率 ÷ P(kW) × 3600</div><p class="model-note">电池实际选型应使用厂家在规定温度、放电率、终止电压与寿命条件下的性能曲线，并考虑功率限制和配置约束。本模型不能替代恒功率 / 恒流放电数据。书 p.92 算例存在单位与算术疑点，详见内容校核说明。</p>`;}
 if(kind==='cooling'){const it=n('it'),cool=n('cool-power'),other=n('other'),dt=n('delta'),pue=(it+cool+other)/it,flow=it/(1.2*1.005*dt);html=`<div class="eyebrow">ENERGY & HEAT</div><h3 style="margin-top:15px">在同一边界中看两种关系</h3><div class="result-metrics"><div class="result-metric"><b>${pue.toFixed(2)}</b><small>恒定功率假设下的 PUE</small></div><div class="result-metric"><b>${flow.toFixed(1)}</b><small>理论风量 / m³/s</small></div><div class="result-metric"><b>${(it+cool+other)}</b><small>设施总功率 / kW</small></div></div><div style="display:flex;height:40px;margin:24px 0;border:1px solid #d6dfcc" aria-label="设施能耗分配"><div style="width:${it/(it+cool+other)*100}%;background:#a6ba94"></div><div style="width:${cool/(it+cool+other)*100}%;background:#7896a3"></div><div style="width:${other/(it+cool+other)*100}%;background:#d8b096"></div></div><small>绿色 IT · 蓝色制冷 · 棕色其他基础设施</small><div class="formula">PUE = 同期设施总能耗 ÷ 同期 IT 能耗<br>在各功率均恒定且持续同一时长时，可约去时长。<br>Q = ρ × cₚ × V̇ × ΔT</div><div class="state-box">单独改变空气温升，会改变理论风量；这里没有联动改变制冷功率。因此不能把“风量变小”直接解释为“全站 PUE 已改善”。</div><p class="model-note">教学假设：全部 IT 功率成为显热；空气密度 ρ=1.2 kg/m³，比热 cₚ=1.005 kJ/(kg·K)，理想均匀流动，未计旁通与回流。温升不是送风温度设定值。<a class="text-link" href="https://www.thegreengrid.org/node/372" target="_blank" rel="noopener">PUE 定义：The Green Grid ↗</a></p>`;}

 $('#lab-output').innerHTML=html;
}

const projectFields=[['requirements','01 需求与边界','说明业务目标、负载增长、运行及维护条件；列出仍缺少的信息。'],['power','02 电力与恢复','描述电源、UPS、后备与分配路径；指出至少一个共同依赖。'],['thermal','03 热量与空间','追踪热量到室外的路径，解释电力中断时冷却恢复的约束。'],['verification','04 验证与运维','写出验收证据、监控责任、变更记录及持续改进方式。']];
function casePage(){setCrumb('京东案例 · 综合评审');return `<div class="eyebrow">THE CAPSTONE / CHAPTER 10</div><h1 class="page-title">把十章知识，放回一座机房。</h1><p class="page-intro">先研读京东华东数据中心的实际案例，再完成一个课程自设的桌面方案。两者分别标注：真实案例帮助理解取舍，教学项目检验你是否能够迁移方法。</p><div class="case-grid"><section class="case-quote"><div class="eyebrow">原书案例 · 2018 年出版背景</div><h2>规划从内部需求展开，<br>实施回到整体边界。</h2><p>原书 p.264 讨论规划与实施的不同推进方向；p.295 强调运维在建设初期介入。把这两处连起来，设计就有了来自运行阶段的反馈。</p><div class="buttons"><a class="button dark" href="#chapter/10">研读完整案例 →</a><button class="text-link" data-source="278">核对原书 p.264 ↗</button></div></section><section style="padding:12px 0"><div class="eyebrow">三个复盘问题</div><div class="path-list">${['为什么电力、冷源和空间需要统一规划？','一套系统在维护和故障时，表现是否相同？','什么证据能说明设计能力在运行中仍然有效？'].map((t,i)=>`<div class="path-step"><span class="path-index">0${i+1}</span><div class="path-title" style="font-size:14px">${t}</div></div>`).join('')}</div></section></div><div class="callout"><h3>先检验十章能否共同支持同一项服务</h3><p>从一次停电、一次变更、一次能效评审和一次交接出发，用前面写过的工程档案重建完整理由。</p><a class="button primary" href="#synthesis">进入四个全书贯通任务 →</a></div><div class="section-head"><h2>你的桌面评审项目</h2><span class="tag red">课程自设情境</span></div><div class="callout"><div class="label">PROJECT BRIEF / 所有数值均为教学假设</div><p>为一座计划部署 100 个机柜的设施准备概念方案。首期平均 IT 需求按每柜 6 kW 假设，未来需要分阶段扩容。业务方要求讨论计划维护时的服务连续性，并说明电源中断后的保障过程。</p><p>已知信息不够支撑最终设计。你的任务是形成问题清单、系统边界、方案取舍与验证计划，而不是选择一个标准等级后直接配置设备。</p></div><div class="callout"><h3>先逐章积累，再形成综合结论</h3><p>每课的工程任务共用这座教学机房。你可以保留原始假设、计算与修改理由，再用下面四个维度总结自己的方案。</p><a class="button primary" href="#project/1">进入十章工程档案 →</a></div><form id="project-form"><div class="project-fields">${projectFields.map(([k,t,p])=>`<label>${t}<textarea class="note-box" data-project="${k}" placeholder="${p}">${esc(state.project[k]||'')}</textarea><small>${p}</small></label>`).join('')}</div>${capstoneReview()}<div class="buttons" style="margin-top:24px"><button class="button primary" type="submit">整理我的评审记录 →</button><button class="button" type="button" data-export="project">导出方案草稿</button></div><div id="project-feedback" aria-live="polite"></div></form><div class="section-head"><h2>评审时，请坚持追问</h2></div>${[['需求','哪些输入是事实，哪些只是尚待确认的假设？'],['路径','任意一个设备退出后，余下路径的能力能否到达负载？'],['耦合','供电恢复与冷却恢复之间，是否存在不同的时间窗口？'],['运营','谁验证、谁维护、谁确认变更后的图纸与现场状态？']].map(([t,b])=>`<details class="recall"><summary>${t} · ${b}</summary><p>把结论写成“在什么条件下成立”，并列出图纸、测试或运行记录作为核验依据。可回到相关章节补充理由。</p></details>`).join('')}`;}
function notesPage(){setCrumb('我的学习记录');const notes=Object.entries(state.notes).filter(([k,v])=>getLesson(k)&&v.trim()),done=lessons.filter(l=>state.done[l.id]).length;return `<div class="eyebrow">YOUR FIELDNOTES</div><h1 class="page-title">让理解留下可回看的痕迹。</h1><p class="page-intro">学习记录保存在当前浏览器。完成度记录学习行为；章节检验反映本课程情境题的表现，两者都不等于工程执业资格。</p><div class="progress-grid"><div class="progress-card"><b>${done} / ${lessons.length}</b><small>完成学习记录</small></div><div class="progress-card"><b>${Object.values(state.quiz).filter(x=>x.passed&&x.version===deepCourse.version).length} / 10</b><small>章节检验通过</small></div><div class="progress-card"><b>${notes.length}</b><small>学习笔记</small></div></div><div class="buttons"><button class="button primary" data-export="notes">导出全部笔记 ↓</button><a class="button" href="#course">继续学习 →</a></div><div class="section-head"><h2>我的笔记</h2></div>${notes.length?notes.map(([id,text])=>{const l=getLesson(id);return `<article class="note-item"><a class="text-link" href="#lesson/${id}/check">第 ${l.chapterId} 章 · ${esc(l.section)} →</a><h3 style="margin-top:9px">${esc(l.title)}</h3><p>${esc(text)}</p></article>`}).join(''):'<div class="callout"><p>在每课的“主动回忆与练习”中写下判断、条件和疑问。你的第一份工程学习笔记会出现在这里。</p></div>'}<div class="section-head"><h2>章节检验记录</h2></div><table class="coverage-table"><thead><tr><th>章节</th><th>最近一次成绩</th><th>状态</th></tr></thead><tbody>${chapters.map(c=>{const q=state.quiz[c.id];return `<tr><td><a href="#chapter/${c.id}/quiz">${c.id}. ${esc(c.shortTitle)} →</a></td><td>${q?`${q.score} / ${c.quiz.length}`:'尚未提交'}</td><td>${q&&q.version!==deepCourse.version?'旧版记录，建议重新检验':q?.passed?'本次全部答对':q?'建议复习后重试':'待检验'}</td></tr>`}).join('')}</tbody></table>`;}
function sourcesPage(){setCrumb('原书索引与内容说明');return `<div class="eyebrow">SOURCE & EDITORIAL NOTES</div><h1 class="page-title">每一课，都能回到它的来处。</h1><p class="page-intro">学习来源为用户提供的《京东数据中心构建实战》，吕科等著，机械工业出版社，2018 年 1 月。文件包含 325 个 PDF 页面，正文书页 1–310 对应 PDF 页 15–324。</p>${sourceFidelityHTML()}<div class="callout"><div class="label">三种内容，三种读法</div><p><strong>原书扫描页：</strong>保留原页内容与图表，作为核对依据。<br><strong>课程解读：</strong>按原书章节与一级节组织，提炼问题、方法、条件和跨章联系；并非逐字转写。<br><strong>教学补充：</strong>情境题、交互模型和综合项目由课程设计，数值与简化假设有明确标注。</p></div><table class="coverage-table"><thead><tr><th>原书章节</th><th>书页</th><th class="optional">PDF 页</th><th>课程单元</th><th>原页</th></tr></thead><tbody>${chapters.map(c=>`<tr><td><a href="#chapter/${c.id}">${c.id}. ${esc(c.shortTitle)}</a></td><td>${c.bookRange.join('–')}</td><td class="optional">${c.bookRange[0]+14}–${c.bookRange[1]+14}</td><td>${c.lessons.length}</td><td><button class="text-link" data-source="${c.bookRange[0]+14}">查看 ↗</button></td></tr>`).join('')}</tbody></table><div class="buttons"><a class="button" href="#reader/1">打开完整原书阅读器 →</a><a class="button" href="#book-guide">阅读作者前言导读 →</a><button class="button" data-source="7">核对作者前言</button><button class="button" data-source="10">原书目录</button></div><div class="section-head"><h2>原文校核与阅读提醒</h2></div><p class="page-intro">扫描文字经本地 OCR 提取并用于检索；数字、公式、两栏目录及表格可能识别有误，应以扫描原页核对。下列问题已检查扫描页，课程保留方法并说明不确定处，不将可疑数值直接转为设计依据。</p>${[{p:26,t:'断路器额定电流的含义',b:'原书写断路器额定电流必须大于下线电缆额定电流，不能机械沿用。课程按设计负载、保护额定或整定值、导体实际允许载流量分别建立关系，并核查动作曲线与保护配合。'},{p:284,t:'冷机容量与计算负荷的口径',b:'书列四台2461 kW按3+1配置，三台名义合计7383 kW；前页计算冷负荷为7427 kW，差44 kW。需核对设备工况、额定值与统计边界，不能仅由这两个数字判断真实工程是否满足要求。'},{p:74,t:'可用性公式的统计口径',b:'原书表达涉及 MTBF / MTTR 口径。理解时需先统一“运行时间”和“完整周期”的定义，课程不直接沿用近似关系作可靠性承诺。'},{p:92,t:'蓄电池算例中的单位与算术',b:'原例存在 W / kW、代入数值及组数计算不一致。课程保留放电曲线和负载需求的选型思路，不直接采用原算例结果。'},{p:142,t:'发电机功率等级的比较',b:'原书功率排序与运行条件的关系需进一步核验。课程以工作时限、负荷特性和具体机型约定理解各类额定值，不照搬排序。'},{p:302,t:'变频泵测试数据的百分数',b:'原表冷冻泵35 Hz行列实测18.26 kW、额定55 kW、功率占比38.2%。复算18.26÷55=33.2%，与原表不同。课程并列保留原值和复算，不能由此确定哪个原始值录入有误。'},{p:301,t:'自然冷却温度与月份的关系',b:'原文关于14℃、12℃对应自然冷却月份的两句理论描述存在方向疑点。课程不直接套用月份，而结合气象、水温、换热器与末端条件讨论。'},{p:283,t:'同一案例的蓄冷时间表述冲突',b:'原书 p.283 写备用 15 min，p.287 写 15 h。课程明确保留这个矛盾，不能据任一数字直接定容，应核对原始项目设计。'}].map(x=>`<div class="note-item"><h3>${x.t}</h3><p>${x.b}</p><button class="text-link" data-source="${x.p+14}">核对书页 ${x.p} ↗</button></div>`).join('')}<div class="section-head"><h2>标准与补充来源</h2></div><p class="page-intro">原书引用的标准和技术背景保留其出版语境。标准版本、产品与项目条件可能变化；网站不作现行合规或认证结论。下面的原始资料用于补充概念边界；Tier 与 PUE 核查于 2026-10-21，过电流保护资料核查于 2026-10-22。</p><div class="connections"><a href="https://www.se.com/us/en/faqs/FAQ000283711/" target="_blank" rel="noopener">Schneider Electric · 设计电流与保护关系 ↗<small>用于核对 I_B ≤ I_n ≤ I_Z 的含义，配合原书 p.26 的阅读说明。</small></a><a href="https://uptimeinstitute.com/tiers" target="_blank" rel="noopener">Uptime Institute · Tier 分类 ↗<small>区分冗余、可并行维护与容错；不把简化实验结果当作认证。</small></a><a href="https://www.thegreengrid.org/node/372" target="_blank" rel="noopener">The Green Grid · PUE ↗<small>明确总能耗与 IT 能耗的统计边界和周期。</small></a></div>`;}
function sourcePageLabel(p){return p>=15&&p<=324?`正文书页 ${p-14}`:p===1?'封面':p===2?'扉页':p===3?'版权页':p===4?'编委会':p<=6?'推荐序':p<=9?'前言':p<=14?'目录':'封底';}
function sourceReader(initial=15,key='book'){activeSourceKey=key;sourcePage=Math.max(1,Math.min(325,Math.round(initial)));state.readerPositions[key]=sourcePage;return `<div class="source-controls"><button class="button small" data-page-step="-1">← 上一页</button><label>PDF 页 <input id="source-page" type="number" min="1" max="325" value="${sourcePage}" aria-label="PDF 页码"></label><button class="button small" data-source-jump>跳转</button><button class="button small" data-page-step="1">下一页 →</button><span id="source-bookpage" class="muted">${sourcePageLabel(sourcePage)}</span></div><div class="reading-source"><img id="reader-image" width="${deepCourse.sourceDimensions?.[sourcePage-1]?.[0]||1190}" height="${deepCourse.sourceDimensions?.[sourcePage-1]?.[1]||1645}" src="assets/pages/${String(sourcePage).padStart(3,'0')}.jpg" alt="原书 PDF 第 ${sourcePage} 页扫描，含原文和图表"></div><p class="source-caption">PDF内嵌原图 · PDF 第 <span id="source-page-label">${sourcePage}</span> / 325 页 · 保留原始像素，无二次压缩 · <a id="reader-original-link" href="assets/pages/${String(sourcePage).padStart(3,'0')}.jpg" target="_blank" rel="noopener">查看原尺寸图 ↗</a></p><details id="ocr-details"><summary style="font-size:12px;color:var(--muted);cursor:pointer">未逐字校订的OCR（仅辅助查找，非准确原文）</summary><div id="ocr-text" class="source-ocr">展开后加载识别文本。</div></details>`;}
function readerPage(p){setCrumb('原书阅读器');return `<div style="max-width:900px;margin:auto"><a class="text-link" href="#sources">← 原书索引与内容说明</a><h1 class="page-title" style="margin-top:20px">原书对照阅读</h1><p class="page-intro">按PDF原始页序显示全部325页图像，包括书前页和封底。各页图像与PDF内嵌原图逐一比对，字节一致；公式、图表、页边注与原书错误均保留。下方OCR未经逐字校订。</p>${sourceReader(Number(p)||state.readerPositions.book||15,'book')}</div>`;}
async function loadOCR(){if(!sourceData)sourceData=await fetch('source-pages.json').then(r=>r.json());const el=$('#ocr-text');if(el)el.textContent=sourceData[sourcePage-1]?.text||'本页未识别到文字。';}
function changePage(p){sourcePage=Math.min(325,Math.max(1,Math.round(p)||15));state.readerPositions[activeSourceKey]=sourcePage;store();if(activeSourceKey==='book'){history.replaceState(null,'','#reader/'+sourcePage);activeRoute=location.hash;state.lastLocation=activeRoute;store();}$('#source-page').value=sourcePage;const size=deepCourse.sourceDimensions?.[sourcePage-1]||[1190,1645];$('#reader-image').width=size[0];$('#reader-image').height=size[1];$('#reader-image').src=`assets/pages/${String(sourcePage).padStart(3,'0')}.jpg`;$('#reader-image').alt=`原书 PDF 第 ${sourcePage} 页扫描`;$('#source-bookpage').textContent=sourcePageLabel(sourcePage);$('#source-page-label').textContent=sourcePage;$('#reader-original-link').href=`assets/pages/${String(sourcePage).padStart(3,'0')}.jpg`;if($('#ocr-details').open)loadOCR().catch(()=>$('#ocr-text').textContent='文字加载失败，请查看扫描页。');}
function showSource(p){p=Math.max(1,Math.min(325,Number(p)));$('#source-title').textContent=`原书 PDF 第 ${p} 页${p>=15&&p<=324?` · 书页 ${p-14}`:''}`;$('#source-body').innerHTML=`<img src="assets/pages/${String(p).padStart(3,'0')}.jpg" alt="原书 PDF 第 ${p} 页"><p class="source-caption">PDF内嵌原图，保留原始像素与页内顺序。课程解释不是逐字原文；有差异时请在上下文中核对。</p><a class="button small" href="#reader/${p}" data-close="source-dialog">进入连续阅读 →</a>`;$('#source-dialog').showModal();}
async function search(query=''){
 const serial=++searchSerial,term=query.trim(),out=$('#search-results');
 const ocrOn=$('#search-ocr')?.checked||false;
 if(!term){out.innerHTML='<div class="search-empty">搜索课程、作者思想、示范、练习与术语。原书 OCR 可在结果底部单独开启，识别内容未经逐字校订。</div>';return;}
 const found=LearningCore.search(courseSearchIndex,term);
 out.innerHTML=`<div class="search-empty" style="padding:8px">${found.length} 项课程结果</div>`+found.slice(0,60).map(d=>`<a href="${d.href}" data-close="search-dialog"><span class="search-kind">${esc(d.kind)}</span><strong style="display:block">${esc(d.title)}</strong><div class="search-snippet">${esc(LearningCore.excerpt(d.text,term))}</div>${d.pages?.length?`<small>${range(d.pages)}</small>`:''}</a>`).join('')+`<label class="search-ocr-toggle"><input id="search-ocr" type="checkbox" ${ocrOn?'checked':''}> 同时检索原书 OCR（未校订，数字与公式须核对扫描页）</label><div id="ocr-search-results"></div>`;
 if(ocrOn){$('#ocr-search-results').textContent='正在检索原书识别文字…';try{if(!sourceData){const r=await fetch('source-pages.json');if(!r.ok)throw Error();sourceData=await r.json();}if(serial!==searchSerial)return;const terms=term.toLowerCase().split(/\s+/).filter(Boolean),hits=sourceData.filter(p=>terms.every(t=>p.text.toLowerCase().replace(/\s+/g,'').includes(t)));$('#ocr-search-results').innerHTML=`<div class="search-empty">原书 OCR：${hits.length} 页</div>`+hits.slice(0,50).map(p=>`<a href="#reader/${p.pdf_page}" data-close="search-dialog">${p.pdf_page>=15&&p.pdf_page<=324?'书页 '+(p.pdf_page-14):'书前页 / 封面'} · PDF ${p.pdf_page}<div class="search-snippet">${esc(LearningCore.excerpt(p.text,term))}</div></a>`).join('');}catch{if(serial===searchSerial)$('#ocr-search-results').textContent='原书识别文字暂时无法加载，课程结果仍可使用。';}}
}
function exportText(kind){let title,body;if(kind==='project'){title='数据中心概念方案-学习草稿';body=`${title}\n课程自设教学情境：100 个机柜，平均每柜 6 kW。\n桌面练习，不是工程设计文件。\n\n`+projectFields.map(([k,t])=>`${t}\n${state.project[k]||'尚未填写'}\n`).join('\n');}else{title='机房之外-学习笔记';body=`${title}\n来源：《京东数据中心构建实战》（2018）课程研读\n\n`+Object.entries(state.notes).filter(([id,v])=>getLesson(id)&&v.trim()).map(([id,v])=>{const l=getLesson(id);return `${l.section} ${l.title}｜${range(l.bookPages)}\n${v}\n`}).join('\n');if(!Object.values(state.notes).some(x=>x.trim()))body+='尚无笔记。\n';}const blob=new Blob([body],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=title+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出文本文件。');}
function render(){if(!course)return;const nextRoute=location.hash||'#home';if(activeRoute===nextRoute)state.positions[activeRoute]=window.scrollY;const route=nextRoute.slice(1).split('/');activeRoute=nextRoute;const [page,id,tab]=route;let html;switch(page){case'home':case'':html=home();break;case'course':html=coursePage();break;case'chapter':{const c=getChapter(id);html=c?(tab==='original'?originalChapterPage(c):tab==='quiz'?quizPage(c):tab==='insight'?insightPage(c):tab==='coverage'?coveragePage(c):tab==='details'?chapterDetailsPage(c):tab==='workshop'?workshopPage(c,route[3]):chapterPage(c)):null;break}case'lesson':{const l=getLesson(id);html=l?lessonPage(l,tab||'read'):null;break}case'systems':html=systemsPage();break;case'labs':html=labsPage(id);break;case'case':html=casePage();break;case'notes':html=notesPage()+reasoningRecordsHTML()+learningRecordTools();break;case'project':html=projectPage(id);break;case'review':html=reviewPage();break;case'synthesis':html=synthesisPage(id);break;case'book-guide':html=bookGuidePage();break;case'original':html=originalPage(id);break;case'book-page':html=bookPageHTML(id);break;case'sources':html=sourcesPage();break;case'reader':html=readerPage(id);break;default:html=null;}
 if(html&&LearningCore.learningRouteExists(nextRoute,chapters)){state.lastLocation=nextRoute;store();} $('#main').innerHTML=html||'<h1 class="page-title">这个学习页面不存在。</h1><a class="button" href="#course">返回课程目录</a>';sidebar();$$('#main details').forEach((el,i)=>{const key=activeRoute+'_'+i;el.dataset.disclosureKey=key;if(state.disclosures[key]!==undefined)el.open=state.disclosures[key];});$$('textarea').forEach(el=>el.maxLength=50000);document.body.classList.remove('nav-open');if(page==='labs')updateLab();$('#ocr-details')?.addEventListener('toggle',e=>{if(e.target.open)loadOCR().catch(()=>$('#ocr-text').textContent='识别文本加载失败，请以扫描页为准。')});window.scrollTo({top:state.positions[activeRoute]||0,behavior:'instant'});if(page==='lesson'&&tab==='details'&&/^p[0-9]+-[0-9]+$/.test(route[3]||''))document.getElementById('detail-'+route[3])?.scrollIntoView({behavior:'instant'});if(page==='original'&&id)loadOriginalPage(Number(id));if(page==='chapter'&&tab==='original')loadOriginalChapter(Number(id));}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();return;}
 if(b.dataset.close){$('#'+b.dataset.close).close();}
 if(b.dataset.scroll){e.preventDefault();const target=document.getElementById(b.dataset.scroll);if(target?.tagName==='DETAILS')target.open=true;target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
 if(b.dataset.layer){activeLayer=b.dataset.layer;$('#hero-diagram').innerHTML=diagram();$('#diagram-highlight').textContent=systems[activeLayer].flow;$$('[data-layer]').forEach(x=>{x.classList.toggle('active',x.dataset.layer===activeLayer);x.setAttribute('aria-pressed',x.dataset.layer===activeLayer)});}
 if(b.dataset.route){state.route=b.dataset.route;state.lastLocation='';state.lastLesson=(lessonOrder().find(l=>!state.done[l.id])||lessonOrder()[0]).id;store();render();}
 if(b.dataset.system){const y=scrollY;systemSelection=b.dataset.system;render();window.scrollTo(0,y);}
 if(b.dataset.source)showSource(b.dataset.source);
 if(b.dataset.pageStep)changePage(sourcePage+Number(b.dataset.pageStep));
 if(b.hasAttribute('data-source-jump'))changePage(Number($('#source-page').value));
 if(b.dataset.answer){const id=b.dataset.answer,l=getLesson(id);state.answers[id]=Number(b.dataset.option);store();b.closest('[data-decision]').outerHTML=decisionHTML(l);}
 if(b.dataset.complete){const l=getLesson(b.dataset.complete);if(state.answers[l.id]!==l.decision.answer){toast('请先完成本课的情境判断，并根据反馈修正理由。');$('[data-decision]').scrollIntoView({block:'center'});return}state.done[l.id]=true;store();sidebar();b.textContent='✓ 已完成学习记录';toast('本课学习记录已保存。可以继续下一课。');}
 if(b.dataset.export)exportText(b.dataset.export);
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;store()}if(el.dataset.project){state.project[el.dataset.project]=el.value;store()}if(el.hasAttribute('data-lab-input'))updateLab();if(el.id==='search-input')search(el.value);});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-lab-input'))updateLab();});
document.addEventListener('submit',e=>{if(e.target.id==='chapter-quiz'){e.preventDefault();const form=e.target,c=getChapter(form.dataset.chapter),data=new FormData(form),choices=c.quiz.map((q,i)=>data.has('q'+i)?Number(data.get('q'+i)):null),grade=LearningCore.gradeQuiz(c.quiz,choices),score=grade.score;c.quiz.forEach((q,i)=>{const selected=choices[i],correct=selected===q.answer;$('#explain-'+i).innerHTML=`<div class="feedback ${correct?'':'wrong'}">${correct?'✓ 判断成立':'需要复习'} · ${esc(q.explanation||q.options[selected]?.feedback||'请对照本题的条件重新分析。')}${q.lessonIds?.length?`<div>${q.lessonIds.map(id=>`<a class="text-link" href="#lesson/${id}/check">回到 ${esc(getLesson(id)?.title||id)} →</a>`).join(' ')}</div>`:''}</div>`;});state.quiz[c.id]={...grade,version:deepCourse.version,date:new Date().toISOString()};store();$('#quiz-result').innerHTML=`<div class="quiz-result">本次 ${score} / ${c.quiz.length} 题答对。${score===c.quiz.length?'已记录通过本章检验。请尝试把方法迁移到综合评审。':'请阅读每题反馈，回到相关单元后再试。'}</div>`;sidebar();$('#quiz-result').scrollIntoView({block:'center'});}
 if(e.target.id==='project-form'){e.preventDefault();$('#project-feedback').innerHTML=capstoneFeedback();}
});
$('#open-search').addEventListener('click',()=>{$('#search-dialog').showModal();search($('#search-input').value);$('#search-input').focus()});$('#menu').addEventListener('click',()=>{document.body.classList.toggle('nav-open');$('#menu').setAttribute('aria-expanded',document.body.classList.contains('nav-open'))});$('#focus').addEventListener('click',()=>{document.body.classList.toggle('focused');const focused=document.body.classList.contains('focused');$('#focus').setAttribute('aria-pressed',focused);$('#focus').setAttribute('aria-label',focused?'退出专注阅读':'切换专注阅读');$('#focus').title=focused?'退出专注阅读':'专注阅读';});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#open-search').click();}if(e.key==='Escape'){document.body.classList.remove('nav-open');$('#menu').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{render();$('#menu').setAttribute('aria-expanded','false');});
Promise.all(['course.json','deep-course.json','original-manifest.json','original-search.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error(url);return r.json()}))).then(([data,deep,original,originalDocs])=>{course=data;deepCourse=deep;originalManifest=original;originalSearch=originalDocs;chapters=data.chapters;const recovered=LearningCore.recoverStoredState(state,chapters);Object.assign(state,recovered.state);if(state.contentVersion!==deepCourse.version){state.answers={};state.contentVersion=deepCourse.version;}if(recovered.warnings)toast("部分无效的旧记录已跳过，其余学习记录已恢复。");for(const c of chapters){const dc=deepChapter(c.id);if(dc?.quiz?.length)c.quiz=dc.quiz;for(const l of c.lessons){const dl=deepLesson(l.id);if(dl?.decision)l.decision=dl.decision;}}lessons=chapters.flatMap(c=>c.lessons.map(l=>({...l,chapterId:c.id})));courseSearchIndex=LearningCore.makeIndex(chapters,deepCourse,glossary);courseSearchIndex.push(...closeReadingSearchDocuments(),...workshopSearchDocuments(),...synthesisSearchDocuments(),...originalSearch.filter(d=>d.status==='proofread'));for(const [id,data] of Object.entries(labInvestigations))courseSearchIndex.push({title:labTypes.find(x=>x[0]===id)[1],kind:"实验与解释",href:"#labs/"+id,text:LearningCore.textOf(data),pages:[]});courseSearchIndex.push({title:"告警与证据",kind:"诊断实验",href:"#labs/alarm",text:LearningCore.textOf(alarmEvidence),pages:[]});render();}).catch(()=>{$('#main').innerHTML='<h1 class="page-title">课程内容暂时无法加载。</h1><p>请确认通过本地服务器或网站地址打开，刷新后重试。</p><button class="button" onclick="location.reload()">重新加载</button>';});

window.addEventListener('scroll',()=>{if(activeRoute&&(location.hash||'#home')===activeRoute)state.positions[activeRoute]=window.scrollY;clearTimeout(positionTimer);positionTimer=setTimeout(store,180);},{passive:true});
window.addEventListener('pagehide',()=>{if(activeRoute)state.positions[activeRoute]=window.scrollY;store();});
document.addEventListener('change',e=>{if(e.target.id==='search-ocr')search($('#search-input').value);});

document.addEventListener('toggle',e=>{const key=e.target.dataset?.disclosureKey;if(key){state.disclosures[key]=e.target.open;store();}},true);
